mapper.select:
SELECT DISTINCT s.seller_id FROM settlement s JOIN settlement_item i ON i.settlement_id=s.settlement_id
JOIN refund r ON r.order_id=i.order_id AND r.status='SUCCESS' AND r.is_deleted=0
WHERE s.status='PAID' AND s.is_deleted=0 AND s.period_end <= #{periodStart}
UNION
SELECT DISTINCT a.seller_id FROM settlement_adjustment a
WHERE a.eligible_from <= #{periodStart}
